arguments.new_string:
# align "=" has been handled
if align == '<':
    s = '%s%s*' % (s, fill)
elif align == '>':
    s = '%s*%s' % (fill, s)
elif align == '^':
    s = '%s*%s%s*' % (fill, s, fill)

return s

arguments.old_string:
# align "=" has been handled
if align == '<':
    # For left-aligned search, consume up to next space
    s = '%s[^%s]*' % (s, fill)
elif align == '>':
    s = '%s*%s' % (fill, s)
elif align == '^':
    # For center-aligned search, consume up to next space on both sides
    s = '[^%s]*%s[^%s]*' % (fill, s, fill)

return s
